npx @tailgrids/cli add input

import { Input } from "@/components/tailgrids/core/input"
import { Label } from "@/components/tailgrids/core/label"
import { useId } from "react"

export default function InputPreview() {
  const id = useId()
  return (
    <div className="grid gap-2">
      <Label htmlFor={id}>Email</Label>
      <Input id={id} type="email" placeholder="Enter your email" autoComplete="email" />
    </div>
  )
}

npx @tailgrids/cli add checkbox

import { Checkbox } from "@/components/tailgrids/core/checkbox"
import { Label } from "@/components/tailgrids/core/label"
import { useId } from "react"

export default function CheckboxExample() {
  const id = useId()
  return (
    <div className="flex items-center gap-3">
      <Checkbox id={id} defaultChecked />
      <Label htmlFor={id}>Accept terms and conditions</Label>
    </div>
  )
}

npx @tailgrids/cli add progress

import { Progress } from "@/components/tailgrids/core/progress"

export default function ProgressBasic() {
  return <Progress progress={50} withLabel />
}

npx @tailgrids/cli add tabs

import {
  TabContent,
  TabList,
  TabRoot,
  TabTrigger
} from "@/components/tailgrids/core/tabs"

export default function TabsExample() {
  return (
    <TabRoot defaultValue="overview">
      <TabList>
        <TabTrigger value="overview">Overview</TabTrigger>
        <TabTrigger value="analytics">Analytics</TabTrigger>
      </TabList>
      <TabContent value="overview"><p>Overview content</p></TabContent>
      <TabContent value="analytics"><p>Analytics content</p></TabContent>
    </TabRoot>
  )
}

